*/

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//

// 	//----W-Craft WebSquare 변환 확인: include----//
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.vCorpRegNo, scwin.vBzProcsNo = "";

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 현재 초기화 로직 없음(구 초기화 로직은 gform_onload 참조).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시점 처리 — 현재 처리 로직 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description 재신청 리스트(dts_List) 조회 완료 콜백 — 그리드 헤더 총 건수를 표시한다.
 * @param {Number} rowcount 조회된 행 수
 * @returns {void}
 * @hidden N
 * @example scwin.dts_List_OnLoadCompleted(dts_List.getRowCount());
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07406.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description 재신청 리스트(dts_List) 조회 실패 콜백 — 오류 내용을 알림으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_List_OnLoadError();
 */
scwin.dts_List_OnLoadError = function() {
    try {
        $c.win.alert(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07406.dts_List_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name listSync
 * @description 법인등록번호·업무처리번호 조건으로 전문평가관리 재신청 리스트(dts_List)를 조회한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.listSync();
 */
scwin.listSync = async function() {
    url += "&CORP_REG_NO=" + scwin.vCorpRegNo; // 법인등록번호
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo; // 업무처리번호

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/lstinvstg/KsqSkilValu.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_List_OnLoadCompleted(dts_List.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name gform_onload
 * @description 구(Gauce) 폼 onload 대응 함수 — 부모창에서 법인등록번호·업무처리번호를 전달받아 재신청 리스트를 조회한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {

    const parentWin = $c.win.getParent();
    scwin.vCorpRegNo = parentWin.scwin.vCorpRegNo;
    scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    scwin.listSync();
};
